CREATE TABLE public.training_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), discipline text NOT NULL, duration_seconds integer NOT NULL DEFAULT 0, strikes integer NOT NULL DEFAULT 0, max_speed numeric NOT NULL DEFAULT 0, simulated boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.training_sessions TO authenticated; GRANT ALL ON public.training_sessions TO service_role;
ALTER TABLE public.training_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own sessions" ON public.training_sessions FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.fighter_settings (user_id uuid PRIMARY KEY, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.fighter_settings TO authenticated; GRANT ALL ON public.fighter_settings TO service_role;
ALTER TABLE public.fighter_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own settings" ON public.fighter_settings FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.sparring_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), filename text NOT NULL, video_path text NOT NULL, discipline text NOT NULL, focus text NOT NULL DEFAULT '', duration_seconds numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'uploaded', report text NOT NULL DEFAULT '', error text);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sparring_reports TO authenticated; GRANT ALL ON public.sparring_reports TO service_role;
ALTER TABLE public.sparring_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own reports" ON public.sparring_reports FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.ai_access_blocks (user_id uuid PRIMARY KEY, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_access_blocks TO authenticated; GRANT ALL ON public.ai_access_blocks TO service_role;
ALTER TABLE public.ai_access_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own AI block" ON public.ai_access_blocks FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY "Private sparring upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='sparring-videos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Private sparring read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='sparring-videos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Private sparring delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='sparring-videos' AND (storage.foldername(name))[1]=auth.uid()::text);